import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"36、【明夷】 离下坤上","description":"温公易说 - 36、【明夷】 离下坤上","frontmatter":{"title":"36、【明夷】 离下坤上","description":"温公易说 - 36、【明夷】 离下坤上"},"headers":[],"relativePath":"zh/classics/wengong/037.md","filePath":"zh/classics/wengong/037.md"}'),n={name:"zh/classics/wengong/037.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_36、【明夷】-离下坤上" tabindex="-1">36、【明夷】 离下坤上 <a class="header-anchor" href="#_36、【明夷】-离下坤上" aria-label="Permalink to “36、【明夷】 离下坤上”">​</a></h1><h3 id="彖曰-明入地中-明夷。内文明而外柔顺-以蒙大难。文王以之-利艰贞。晦其明也-内难而能正其志-箕子以之。" tabindex="-1">彖曰：明入地中，明夷。内文明而外柔顺，以蒙大难。文王以之，利艰贞。晦其明也，内难而能正其志，箕子以之。 <a class="header-anchor" href="#彖曰-明入地中-明夷。内文明而外柔顺-以蒙大难。文王以之-利艰贞。晦其明也-内难而能正其志-箕子以之。" aria-label="Permalink to “彖曰：明入地中，明夷。内文明而外柔顺，以蒙大难。文王以之，利艰贞。晦其明也，内难而能正其志，箕子以之。”">​</a></h3><h3 id="象曰-明入地中-明夷。君子以莅众-用晦而明。" tabindex="-1">象曰：明入地中，明夷。君子以莅众，用晦而明。 <a class="header-anchor" href="#象曰-明入地中-明夷。君子以莅众-用晦而明。" aria-label="Permalink to “象曰：明入地中，明夷。君子以莅众，用晦而明。”">​</a></h3><h3 id="初九-明夷于飞-垂其翼。君子于行-三日不食-有攸往-主人有言-象曰-君子于义-不食也。" tabindex="-1">初九：明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言 象曰：君子于义，不食也。 <a class="header-anchor" href="#初九-明夷于飞-垂其翼。君子于行-三日不食-有攸往-主人有言-象曰-君子于义-不食也。" aria-label="Permalink to “初九：明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言 象曰：君子于义，不食也。”">​</a></h3><h3 id="六二-明夷夷于左股-用拯马壮-吉-象曰-六二之吉-顺以则也。" tabindex="-1">六二：明夷夷于左股，用拯马壮，吉 象曰：六二之吉，顺以则也。 <a class="header-anchor" href="#六二-明夷夷于左股-用拯马壮-吉-象曰-六二之吉-顺以则也。" aria-label="Permalink to “六二：明夷夷于左股，用拯马壮，吉 象曰：六二之吉，顺以则也。”">​</a></h3><h3 id="九三-明夷于南狩-得其大首-不可疾贞-象曰-南狩之志-乃大得也。" tabindex="-1">九三：明夷于南狩，得其大首，不可疾贞 象曰：南狩之志，乃大得也。 <a class="header-anchor" href="#九三-明夷于南狩-得其大首-不可疾贞-象曰-南狩之志-乃大得也。" aria-label="Permalink to “九三：明夷于南狩，得其大首，不可疾贞 象曰：南狩之志，乃大得也。”">​</a></h3><h3 id="六四-入于左腹-获明夷之心-于出门庭-象曰-入于左腹-获心意也。" tabindex="-1">六四：入于左腹，获明夷之心，于出门庭 象曰：入于左腹，获心意也。 <a class="header-anchor" href="#六四-入于左腹-获明夷之心-于出门庭-象曰-入于左腹-获心意也。" aria-label="Permalink to “六四：入于左腹，获明夷之心，于出门庭 象曰：入于左腹，获心意也。”">​</a></h3><h3 id="六五-箕子之明夷-利贞-象曰-箕子之贞-明不可息也。" tabindex="-1">六五：箕子之明夷，利贞 象曰：箕子之贞，明不可息也。 <a class="header-anchor" href="#六五-箕子之明夷-利贞-象曰-箕子之贞-明不可息也。" aria-label="Permalink to “六五：箕子之明夷，利贞 象曰：箕子之贞，明不可息也。”">​</a></h3><p>君子之晦，以避难也。内修明德，不可息也。为人臣者，有箕子之正，则可也。无箕子之正，茍生以忘其君者，罪莫大焉。故曰利贞。</p><h3 id="上六-不明晦-初登于天-后入于地-象曰-初登于天-照四国也。后入于地-失则也。" tabindex="-1">上六：不明晦，初登于天，后入于地 象曰：初登于天，照四国也。后入于地，失则也。 <a class="header-anchor" href="#上六-不明晦-初登于天-后入于地-象曰-初登于天-照四国也。后入于地-失则也。" aria-label="Permalink to “上六：不明晦，初登于天，后入于地 象曰：初登于天，照四国也。后入于地，失则也。”">​</a></h3><p>上六之象，其言失则。何国家之所以立者，法也。故为工者，规矩绳墨不可去也。为国者，礼乐法度不可失也。度差而机失，纲绝而网紊，纪散而乱。法坏则国家从之。呜呼，为人君者，可不慎哉。鲁有庆父之难，齐桓公使仲孙湫视之，曰：鲁可取乎？对曰：不可，犹秉周礼。周礼所以本也。然则法之于国，岂不重哉。</p>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
